import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogTitle from '@mui/material/DialogTitle';
import Button from '@mui/material/Button';
import Typography from '@mui/material/Typography';

export default function HostedGameRecoveryDialog({ gameStarted, onRejoin, onEndGame }:
    { gameStarted: boolean, onRejoin: () => void, onEndGame: () => void }) {
    return <Dialog open aria-labelledby='hosted-game-recovery-title'>
        <DialogTitle id='hosted-game-recovery-title'>Hosted Game Found</DialogTitle>
        <DialogContent>
            <Typography>You still have a session in progress. Would you like to rejoin it or end it for everyone?</Typography>
        </DialogContent>
        <DialogActions>
            <Button onClick={onEndGame} variant='contained' color='error'>End Game</Button>
            <Button onClick={onRejoin} variant='contained'>Rejoin {gameStarted ? 'Game' : 'Room'}</Button>
        </DialogActions>
    </Dialog>;
}
