import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogTitle from '@mui/material/DialogTitle';
import Typography from '@mui/material/Typography';

export default function PlayerGameRecoveryDialog({ onRejoin, onLeave }:
    { onRejoin: () => void, onLeave: () => void }) {
    return <Dialog open aria-labelledby='player-game-recovery-title'>
        <DialogTitle id='player-game-recovery-title'>Game in Progress</DialogTitle>
        <DialogContent>
            <Typography>Your previous game may still be running. Would you like to rejoin it?</Typography>
        </DialogContent>
        <DialogActions>
            <Button onClick={onLeave} variant='contained' color='error'>Leave Game</Button>
            <Button onClick={onRejoin} variant='contained'>Rejoin Game</Button>
        </DialogActions>
    </Dialog>;
}
