import Button from '@mui/material/Button';
import Stack from '@mui/material/Stack';
import TextField from '@mui/material/TextField';
import Typography from '@mui/material/Typography';
import * as React from 'react';
import Grid from '@mui/material/Grid';
import { useAppDispatch, useAppSelector } from '../store/hooks';
import { startPeer, setUserData } from '../store/peer/peerActions';
import { changeConnectionInput, clearExpiredGame, connectPeer, endHostedGame, updateGameState } from '../store/connection/connectionActions';
import { useNavigate } from 'react-router';
import { MuiColorInput, MuiColorInputColors } from 'mui-color-input';
import { PeerState, UserData } from '../store/peer/peerTypes';
import CardContent from '@mui/material/CardContent';
import Card from '@mui/material/Card';
import { Filter } from 'bad-words'
import Divider from '@mui/material/Divider';
import { blankPiece, initialState } from '../store/connection/connectionReducer';
import { ConnectionState } from '../helpers/common';
import { themeOptions } from '../helpers/theme';
import Box from '@mui/material/Box';
import { PeerConnection } from '../helpers/peer';
import HostedGameRecoveryDialog from './HostedGameRecoveryDialog';
import PlayerGameRecoveryDialog from './PlayerGameRecoveryDialog';
import { createGameId, isGameExpired } from '../helpers/gameExpiry';


function Home() {
  const [userDataError, setUserDataError] = React.useState<string>();
  const peer = useAppSelector((state) => state.peer) as PeerState;
  const connection = useAppSelector((state) => state.connection) as ConnectionState;
  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const [isEnteringRoom, setIsEnteringRoom] = React.useState(false);
  const filter = new Filter();
  filter.removeWords('hells', 'sadist', 'hell');

  const [userDataInfo, setUserDataInfo] = React.useState<UserData>({ color: peer.userData?.color ?? '#fff', userName: peer.userData?.userName ?? undefined });
  const gameExpired = isGameExpired(connection.gameState);
  const hostedSessionAvailable = !isEnteringRoom && !gameExpired && connection.gameState.hostId === peer.id && !connection.gameState.gameEnded;
  const hasRecoveredCurrentGame = connection.recoveredGameId !== undefined
    && connection.recoveredGameId === connection.gameState.gameId;
  const playerSessionAvailable = !isEnteringRoom && !hasRecoveredCurrentGame && !gameExpired && connection.gameState.started && !connection.gameState.gameEnded
    && connection.gameState.hostId !== undefined && connection.gameState.hostId !== peer.id
    && connection.gameState.gameId !== undefined
    && connection.gameState.lobby.playerList.some(player => player.user.id === peer.id);

  React.useEffect(() => {
    if (gameExpired) dispatch(clearExpiredGame());
  }, [dispatch, gameExpired]);

  React.useEffect(() => {
    if (connection.recoveredGameId !== undefined && connection.recoveredGameId === connection.gameState.gameId) {
      navigate('/Game');
    }
  }, [connection.gameState.gameId, connection.recoveredGameId, navigate]);

  const ensurePeerSession = async () => PeerConnection.getPeer()?.id ?? await dispatch(startPeer(peer.id));

  const handleConnectOtherPeer = async () => {
    setIsEnteringRoom(true);
    const localPeerId = await ensurePeerSession();
    if (!localPeerId) {
      setIsEnteringRoom(false);
      return;
    }
    await connectToPeer(localPeerId);
    navigate('/Room');
  }

  const connectToPeer = (localPeerId: string) => {
    return dispatch(connectPeer(connection.id!, {
      userName: peer.userData.userName!,
      color: peer.userData.color!,
      id: localPeerId
    }));
  }

  const handleSetHosting = async () => {
    setIsEnteringRoom(true);
    // The first peer session resolves asynchronously. Pass its returned id
    // through instead of reading the stale selector value from this render.
    const hostId = await ensurePeerSession();
    if (!hostId) {
      setIsEnteringRoom(false);
      return;
    }
    startGame(hostId);
  }

  const startGame = (hostId: string) => {
    dispatch(updateGameState({
      ...initialState.gameState,
      createdAt: Date.now(),
      gameId: createGameId(),
      hostId,
      lobby: {
        ...initialState.gameState.lobby,
        playerList: [{
          user: { color: peer.userData.color!, userName: peer.userData.userName!, id: hostId },
          piece: { ...blankPiece }
        }]
      }
    }));
    navigate('/Room');
  }

  const handleRejoinHostedSession = async () => {
    const hostId = await ensurePeerSession();
    if (!hostId || hostId !== connection.gameState.hostId) return;
    navigate(connection.gameState.started ? '/Game' : '/Room');
  };

  const handleEndHostedSession = async () => {
    const hostId = await ensurePeerSession();
    if (!hostId || hostId !== connection.gameState.hostId) return;
    dispatch(endHostedGame());
  };

  const handleRejoinPlayerSession = async () => {
    const hostId = connection.gameState.hostId;
    const gameId = connection.gameState.gameId;
    const localPeerId = await ensurePeerSession();
    if (!hostId || !gameId || !localPeerId || !peer.userData?.userName || !peer.userData.color) return;
    await dispatch(connectPeer(hostId, {
      id: localPeerId,
      userName: peer.userData.userName,
      color: peer.userData.color
    }, gameId));
  };

  const validateUser = (userName: string) => {
    if (filter.isProfane(userName)) {
      setUserDataError('User Name must not be profane.');
      return false;
    }
    else if (userName.length < 5) {
      setUserDataError('User Name must exceed 5 characters.')
      return false;
    }

    setUserDataError(undefined);
    return true;
  }

  return (
    <div className='parentBox homePage'>
      <Card sx={{ backgroundColor: themeOptions.palette!.background!.default!, width: '100%' }}>
        <CardContent sx={{ paddingBottom: '0!important', padding: { xs: 2, sm: 3 } }}>
          <Grid columns={16} sx={{ marginBottom: 2 }}>
            <Box component='img' src={`${import.meta.env.BASE_URL}/sh_text_logo.png`} alt='Shadow Hunters Logo'
              sx={{ display: 'block', width: { xs: '100%', sm: '70%' }, maxWidth: 460, paddingBottom: 1}} />
            <Divider variant='fullWidth' />
          </Grid>
          <Grid columns={16} display='flex' justifyContent='center'>
            <Card sx={{ width: '100%' }}>
              <CardContent>
                <Typography variant='h5' gutterBottom align='left'>
                  User Info
                </Typography>
                <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}
                  sx={{
                    justifyContent: 'space-between',
                    alignItems: 'stretch',
                  }}>
                  <TextField error={userDataError !== undefined} helperText={userDataError} fullWidth label='User Name' variant='outlined'
                    onChange={(e: React.ChangeEvent<HTMLInputElement>) => {
                      setUserDataInfo({ userName: e.target.value, color: userDataInfo.color });
                      dispatch(setUserData({ userName: e.target.value, color: userDataInfo.color }));
                      validateUser(e.target.value);
                    }} value={userDataInfo.userName!} />
                  <MuiColorInput label='User Color' fullWidth format='hex' onChange={(_value: string, colors: MuiColorInputColors) => {
                    setUserDataInfo({ userName: userDataInfo.userName, color: colors.hex });
                    dispatch(setUserData({ userName: userDataInfo.userName, color: colors.hex }));
                  }} value={userDataInfo.color!} />
                </Stack>
              </CardContent>
            </Card>
          </Grid>
          <Grid columns={16} display='flex' justifyContent='center'>
            <Card sx={{ width: '100%' }}>
              <CardContent>
                <Typography variant='h5' gutterBottom align='left'>
                  Game Room
                </Typography>
                <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}
                  sx={{
                    justifyContent: 'space-between',
                    alignItems: 'stretch',
                    paddingBottom: 2
                  }}>
                  <TextField fullWidth label='Room Code' variant='outlined' onChange={(e: React.ChangeEvent<HTMLInputElement>) => dispatch(changeConnectionInput(e.target.value === '' ? undefined : e.target.value))
                  } />
                  <Button sx={{ width: { xs: '100%', sm: 'auto' }, flexShrink: 0 }} size='large' disabled={connection.id === undefined || userDataInfo.userName === undefined || userDataError !== undefined} variant='contained'
                    onClick={handleConnectOtherPeer}>Join</Button>
                </Stack>
                <Divider />
                <Stack direction={'row'} spacing={2}
                  sx={{
                    justifyContent: 'right',
                    alignItems: 'stretch',
                    paddingTop: 2
                  }}>
                  <Button sx={{ width: { xs: '100%', sm: 'auto' } }} size='large' disabled={userDataError !== undefined || userDataInfo.userName === undefined || userDataInfo.userName === ''} variant='contained' onClick={handleSetHosting}>Create Room</Button>
                </Stack>
              </CardContent>
            </Card>
          </Grid>
        </CardContent>
      </Card>
      {hostedSessionAvailable ? <HostedGameRecoveryDialog
        gameStarted={connection.gameState.started}
        onRejoin={handleRejoinHostedSession}
        onEndGame={handleEndHostedSession} /> : undefined}
      {playerSessionAvailable ? <PlayerGameRecoveryDialog
        onRejoin={handleRejoinPlayerSession}
        onLeave={() => dispatch(clearExpiredGame())} /> : undefined}
    </div >
  );
}

export default Home;
